<form class="be_filters" method="get" action="<?= e(url('users')) ?>"><select name="field" aria-label="<?= e(t('users.search_in')) ?>"><option value=""><?= e(t('users.search_all')) ?></option><?php foreach (['given' => 'users.f_given', 'family' => 'users.f_family', 'username' => 'users.f_username', 'email' => 'users.f_email'] as $fk => $fl): ?><option value="<?= $fk ?>"<?= ($field ?? '') === $fk ? ' selected' : '' ?>><?= e(t($fl)) ?></option><?php endforeach; ?></select>
