<table class="be_table"><thead><tr><th><?= e(t('users.f_given')) ?></th><th><?= e(t('users.f_family')) ?></th><th><?= e(t('users.f_username')) ?></th><th><?= e(t('users.f_email')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr class="<?= $r['disabled'] ? 'be_muted_row' : '' ?>"><td><?= e($r['given_name']) ?><?= $r['disabled'] ? ' <em>(' . e(t('users.disabled')) . ')</em>' : '' ?></td><td><?= e($r['family_name']) ?></td><td><?= e($r['username']) ?></td><td><?= e($r['email']) ?></td>
<td class="be_actions"><form method="post" class="be_inline"><?= csrf_field() ?><a class="be_btn" href="<?= e(url('users', 'form', [$r['id']])) ?>"><?= e(t('users.edit_user')) ?></a><a class="be_btn" href="<?= e(url('users', 'editRoles', [$r['id']])) ?>"><?= e(t('users.edit_roles')) ?></a><a class="be_btn" href="<?= e(url('users', 'email', [$r['id']])) ?>"><?= e(t('users.email')) ?></a>
<?php if ((int)$r['id'] !== $me): ?><?php if (!$r['disabled']): ?><button class="be_btn" type="submit" formaction="<?= e(url('user', 'loginAs', [$r['id']])) ?>"><?= e(t('users.login_as')) ?></button><?php endif; ?>
